# Fact Atomization Engine - runnable demo (JAH-ATK175S-000001)
import re
RANK = 1
SIG = True
TEXT = 'The library opened in 1911 and holds two million books, which include rare manuscripts.'
parts = re.split(r"\s*(?:;|\s+and\s+|\s+but\s+|\s+which\s+)\s*", TEXT)
sents = []
for p in parts:
    sents.extend([s.strip() for s in re.split(r"(?<=[.!?])\s+", p) if s.strip()])
atoms, seen = [], set()
for s in sents:
    s = s.rstrip(".")
    if s and s.lower() not in seen:
        seen.add(s.lower()); atoms.append(s)
print("source sentences: %d -> atoms: %d" % (len(re.split(r"(?<=[.!?])\s+", TEXT)), len(atoms)))
for i, a in enumerate(atoms, 1):
    print("  atom%d: %s" % (i, a[:75]))
    if RANK >= 2 and len(a.split()) < 4: print("    (flag: very short, review)")
if RANK >= 3:
    print("deduped:", len(sents) - len(atoms), "fragments")
if SIG:
    print("Signature lineage stamp: JAH-SIG-ATM-" + "JAH-ATK175S-000001")
print("record:", "JAH-ATK175S-000001", "OK")

